     9→    public class LogEntry(Address address, byte[] data, Hash256[] topics) : ILogEntry
    10→    {
    11→        public Address Address { get; } = address;
    12→        public Hash256[] Topics { get; } = topics;
    13→        public byte[] Data { get; } = data;
    14→    }
